// Package invui draws menus in a chest window kept open while the server
// rewrites its slots: every element of a screen is a slot whose item and
// name the inventoryui pack's sg_menu.json draws (generated by
// tools/invuigen from this layout), and a press on a slot drops one item,
// which the server cancels and answers.
package invui

// Marker in the window title makes the pack draw the menu window.
const Marker = "§s§g§m§u"

// The slots every screen shares: the screen's key, its title, its body
// text, a second text (a split screen's status) and the page arrows of a
// split screen.
const (
	SlotKey   = 0
	SlotTitle = 1
	SlotBody  = 2
	SlotInfo  = 3
	SlotPrev  = 4
	SlotNext  = 5
)

// Tabs are the tabs over the window: an icon and a button slot each.
const (
	Tabs     = 8
	TabIcon0 = 6
	TabBtn0  = TabIcon0 + Tabs
)

// Bars are the buttons of the control bar, left of the close button.
const (
	Bars     = 6
	BarIcon0 = TabBtn0 + Tabs
	BarBtn0  = BarIcon0 + Bars
)

// Rows are the elements with an icon and a label: an icon and a button slot
// each. The screen's layout draws them as list rows, cards or actions.
const (
	Rows     = 48
	RowIcon0 = BarBtn0 + Bars
	RowBtn0  = RowIcon0 + Rows
)

// Cells are the item slots of a screen's grid: one slot each, holding the
// item itself named with its tooltip.
const (
	Cells = 113
	Cell0 = RowBtn0 + Rows
)

// Size is the number of slots of the menu window.
const Size = Cell0 + Cells

// The layouts of the screens, by the key in SlotKey.
const (
	KeyMenu      = "mn"
	KeyCards     = "cd"
	KeyGrid      = "gd"
	KeyBoard     = "bd"
	KeySplit     = "sp"
	KeyListSplit = "ls"
)

// The columns of the cell grids of the layouts.
const (
	GridColumns  = 17
	BoardColumns = 11
	SplitColumns = 8
	SplitCells   = 48
	RightColumns = 7
	CardColumns  = 4
	ListRows     = 32
)

// Kind markers end a slot's name and say what the slot draws. They are
// invisible format codes the pack takes off the text.
const (
	KindRow       = "§z§a"
	KindStatic    = "§z§s"
	KindChosen    = "§z§c"
	KindHeading   = "§z§h"
	KindDivider   = "§z§d"
	KindToggleOff = "§z§o"
	KindToggleOn  = "§z§x"
	KindTab       = "§z§t"
	KindTabOn     = "§z§u"
	KindBar       = "§z§b"
	KindHelp      = "§z§q"
	KindIcon      = "§z§i"
	KindFrame     = "§z§f"
	KindArrow     = "§z§w"
	KindText      = "§z§y"
	KindMini      = "§z§m"
	KindMiniView  = "§z§n"
	KindBlank     = "§z§e"
)

// Kinds are the kind markers in the order the pack strips them.
var Kinds = []string{KindRow, KindStatic, KindChosen, KindHeading, KindDivider, KindToggleOff, KindToggleOn, KindTab, KindTabOn, KindBar, KindHelp, KindIcon, KindFrame, KindArrow, KindText, KindMini, KindMiniView, KindBlank}
